/**
 * Windowed behavioural features for the trained classifier.
 *
 * THE PARITY CONTRACT: this is a port of `ml/drowsyguard_ml/features.py`. The
 * model only means anything if the browser computes what training computed, so
 * `mlFeatures.test.ts` replays a fixture generated by the Python code. Change
 * one file and you must change the other and regenerate that fixture.
 *
 * Like `drowsiness.ts`, nothing here reads a clock or touches the camera.
 */
import { LEFT_EYE, RIGHT_EYE } from './landmarks';
import { eyeAspectRatio, headPose, mouthAspectRatio, type Point } from './geometry';

export interface FeatureConfig {
  sample_hz: number;
  window_s: number;
  min_window_s: number;
  recent_s: number;
  min_visible_frac: number;
  calibration_s: number;
  calibration_min_frames: number;
  calibration_min_ear: number;
  calibration_trim: number;
  closure_ratio: number;
  deep_closure_ratio: number;
  blink_max_ms: number;
  long_closure_ms: number;
  yawn_ratio: number;
  yawn_margin: number;
  yawn_hold_ms: number;
  nod_degrees: number;
  nod_hold_ms: number;
  head_down_degrees: number;
  head_speed_max_gap_ms: number;
}

export interface Calibration {
  ear: number;
  mar: number;
  pitch: number;
  yaw: number;
  roll: number;
}

/** One thinned sample. Signals are NaN when no face was found. */
export interface MlSample {
  t: number;
  ear: number;
  earL: number;
  earR: number;
  mar: number;
  pitch: number;
  yaw: number;
  roll: number;
}

export type Measured = Omit<MlSample, 't'>;

export const NO_FACE: Measured = {
  ear: NaN, earL: NaN, earR: NaN, mar: NaN, pitch: NaN, yaw: NaN, roll: NaN,
};

/**
 * Same ratios as the dashboard, but with y rescaled by the aspect ratio first.
 * Training footage is 16:9, 4:3 and portrait, and normalised coordinates would
 * give one eye a different EAR in each. The dashboard's EAR is left as it was.
 */
export function measureForModel(points: Point[], aspect: number): Measured {
  const scaled = points.map((p) => ({ x: p.x, y: p.y / (aspect || 1), z: p.z }));
  const earL = eyeAspectRatio(scaled, LEFT_EYE);
  const earR = eyeAspectRatio(scaled, RIGHT_EYE);
  // Already aspect-corrected, so the pose must not rescale again.
  const pose = headPose(scaled, 1);
  return {
    ear: (earL + earR) / 2,
    earL,
    earR,
    mar: mouthAspectRatio(scaled),
    pitch: pose?.pitch ?? NaN,
    yaw: pose?.yaw ?? NaN,
    roll: pose?.roll ?? NaN,
  };
}

const mean = (v: number[]): number => (v.length ? v.reduce((s, x) => s + x, 0) / v.length : 0);

function std(v: number[]): number {
  if (!v.length) return 0;
  const m = mean(v);
  return Math.sqrt(v.reduce((s, x) => s + (x - m) ** 2, 0) / v.length);
}

function percentile(sorted: number[], q: number): number {
  if (!sorted.length) return 0;
  const pos = (sorted.length - 1) * q;
  const lo = Math.floor(pos);
  const hi = Math.min(lo + 1, sorted.length - 1);
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (pos - lo);
}

function slopePerMinute(ts: number[], ys: number[]): number {
  if (ts.length < 2) return 0;
  const mt = mean(ts);
  const my = mean(ys);
  let num = 0;
  let den = 0;
  for (let i = 0; i < ts.length; i++) {
    num += (ts[i] - mt) * (ys[i] - my);
    den += (ts[i] - mt) ** 2;
  }
  return den === 0 ? 0 : (num / den) * 60000;
}

function runs(flags: boolean[]): [number, number][] {
  const out: [number, number][] = [];
  let start = -1;
  flags.forEach((flag, i) => {
    if (flag && start < 0) start = i;
    else if (!flag && start >= 0) {
      out.push([start, i - 1]);
      start = -1;
    }
  });
  if (start >= 0) out.push([start, flags.length - 1]);
  return out;
}

function trimmed(values: number[], trim: number): number {
  const s = [...values].sort((a, b) => a - b);
  const cut = Math.floor(s.length * trim);
  return mean(s.length - 2 * cut > 0 ? s.slice(cut, s.length - cut) : s);
}

/** Baseline from the first `calibration_s` of samples, or null if they cannot support one. */
export function calibrate(samples: readonly MlSample[], cfg: FeatureConfig): Calibration | null {
  if (!samples.length) return null;
  const end = samples[0].t + cfg.calibration_s * 1000;
  const used = samples.filter((s) => s.t < end && !Number.isNaN(s.ear));
  if (used.length < cfg.calibration_min_frames) return null;
  const pick = (k: keyof Measured) => trimmed(used.map((s) => s[k]), cfg.calibration_trim);
  const ear = pick('ear');
  if (ear < cfg.calibration_min_ear) return null;
  return { ear, mar: pick('mar'), pitch: pick('pitch'), yaw: pick('yaw'), roll: pick('roll') };
}

/** Features in training order, or null when the window cannot support a prediction. */
export function windowFeatures(s: readonly MlSample[], cal: Calibration, cfg: FeatureConfig): number[] | null {
  const n = s.length;
  if (n < 2) return null;
  const period = 1000 / cfg.sample_hz;
  const valid = s.map((x) => !Number.isNaN(x.ear));
  const idx: number[] = [];
  valid.forEach((v, i) => v && idx.push(i));
  const visible = idx.length / n;
  const spanMs = s[n - 1].t - s[0].t;
  if (visible < cfg.min_visible_frac || spanMs < cfg.min_window_s * 1000 - 2 * period) return null;
  const minutes = (spanMs * visible) / 60000;
  const halfMinutes = minutes / 2;
  const tMid = (s[0].t + s[n - 1].t) / 2;
  const tRecent = s[n - 1].t - cfg.recent_s * 1000;

  const rel = s.map((x, i) => (valid[i] ? x.ear / cal.ear : 0));
  const relValid = idx.map((i) => rel[i]);
  const closed = rel.map((r, i) => valid[i] && r < cfg.closure_ratio);
  const deep = rel.map((r, i) => valid[i] && r < cfg.deep_closure_ratio);

  const closedShare = (lo: number, hi: number): number => {
    let total = 0;
    let shut = 0;
    for (const i of idx) {
      if (s[i].t >= lo && s[i].t <= hi) {
        total += 1;
        if (closed[i]) shut += 1;
      }
    }
    return total ? (shut / total) * 100 : 0;
  };

  const closureDurs: number[] = [];
  const blinkDurs: number[] = [];
  const blinkAmps: number[] = [];
  const blinkVels: number[] = [];
  const blinkStarts: number[] = [];
  let longCount = 0;
  for (const [a, b] of runs(closed)) {
    const dur = s[b].t - s[a].t + period;
    closureDurs.push(dur);
    if (dur >= cfg.long_closure_ms) longCount += 1;
    if (dur <= cfg.blink_max_ms) {
      let lowest = a;
      for (let i = a; i <= b; i++) if (rel[i] < rel[lowest]) lowest = i;
      blinkDurs.push(dur);
      blinkStarts.push(s[a].t);
      blinkAmps.push(1 - rel[lowest]);
      if (b + 1 < n && valid[b + 1] && s[b + 1].t > s[lowest].t) {
        blinkVels.push((rel[b + 1] - rel[lowest]) / ((s[b + 1].t - s[lowest].t) / 1000));
      }
    }
  }

  const intervals: number[] = [];
  for (let i = 0; i + 1 < blinkStarts.length; i++) intervals.push(blinkStarts[i + 1] - blinkStarts[i]);
  const intervalMean = mean(intervals);
  const blinksFirst = blinkStarts.filter((t) => t < tMid).length;
  const blinksSecond = blinkStarts.length - blinksFirst;

  const marValid = idx.map((i) => s[i].mar);
  const marRel = marValid.map((v) => v - cal.mar);
  const yawnLimit = Math.max(cfg.yawn_ratio, cal.mar + cfg.yawn_margin);
  let yawnMs = 0;
  let yawns = 0;
  for (const [a, b] of runs(s.map((x, i) => valid[i] && x.mar > yawnLimit))) {
    const dur = s[b].t - s[a].t + period;
    if (dur >= cfg.yawn_hold_ms) {
      yawns += 1;
      yawnMs += dur;
    }
  }

  const pitchRel = s.map((x, i) => (valid[i] ? x.pitch - cal.pitch : 0));
  const pitchValid = idx.map((i) => pitchRel[i]);
  let nods = 0;
  for (const [a, b] of runs(pitchRel.map((p, i) => valid[i] && p <= -cfg.nod_degrees))) {
    if (s[b].t - s[a].t + period >= cfg.nod_hold_ms) nods += 1;
  }
  const down = idx.filter((i) => pitchRel[i] <= -cfg.head_down_degrees).length;
  const speeds: number[] = [];
  for (let i = 1; i < n; i++) {
    const dt = s[i].t - s[i - 1].t;
    if (valid[i] && valid[i - 1] && dt > 0 && dt <= cfg.head_speed_max_gap_ms) {
      const step = Math.sqrt(
        (s[i].pitch - s[i - 1].pitch) ** 2 + (s[i].yaw - s[i - 1].yaw) ** 2 + (s[i].roll - s[i - 1].roll) ** 2,
      );
      speeds.push(step / (dt / 1000));
    }
  }

  const firstPitch = idx.filter((i) => s[i].t < tMid).map((i) => pitchRel[i]);
  const secondPitch = idx.filter((i) => s[i].t >= tMid).map((i) => pitchRel[i]);
  const sortedRel = [...relValid].sort((a, b) => a - b);

  return [
    mean(idx.map((i) => s[i].ear)),
    mean(relValid),
    std(relValid),
    percentile(sortedRel, 0.1),
    percentile(sortedRel, 0.5),
    mean(idx.map((i) => (s[i].ear > 0 ? Math.abs(s[i].earL - s[i].earR) / s[i].ear : 0))),
    closedShare(s[0].t, s[n - 1].t),
    (idx.filter((i) => deep[i]).length / idx.length) * 100,
    closedShare(tRecent, s[n - 1].t),
    blinkDurs.length / minutes,
    mean(blinkDurs),
    blinkDurs.length ? Math.max(...blinkDurs) : 0,
    mean(blinkAmps),
    mean(blinkVels),
    intervals.length >= 2 && intervalMean > 0 ? std(intervals) / intervalMean : 0,
    longCount / minutes,
    closureDurs.length ? Math.max(...closureDurs) : 0,
    mean(closureDurs),
    mean(marRel),
    std(marValid),
    marRel.reduce((m, v) => Math.max(m, v), -Infinity),
    yawns / minutes,
    yawnMs / (spanMs * visible),
    mean(pitchValid),
    std(pitchValid),
    pitchValid.reduce((m, v) => Math.min(m, v), Infinity),
    std(idx.map((i) => s[i].yaw)),
    std(idx.map((i) => s[i].roll)),
    mean(speeds),
    nods / minutes,
    down / idx.length,
    slopePerMinute(idx.map((i) => s[i].t), relValid),
    closedShare(tMid, s[n - 1].t) - closedShare(s[0].t, tMid - 1e-9),
    (blinksSecond - blinksFirst) / halfMinutes,
    mean(secondPitch) - mean(firstPitch),
    visible,
  ];
}

/** Thins live frames to the training sample rate and holds the rolling window. */
export class FeatureWindow {
  private samples: MlSample[] = [];
  private nextT: number | null = null;
  private cal: Calibration | null = null;
  private calibrationSamples: MlSample[] = [];

  constructor(private cfg: FeatureConfig) {}

  get calibration(): Calibration | null {
    return this.cal;
  }

  /** Seconds of history currently held, which drives the warm-up display. */
  get heldSeconds(): number {
    const n = this.samples.length;
    return n < 2 ? 0 : (this.samples[n - 1].t - this.samples[0].t) / 1000;
  }

  reset(): void {
    this.samples = [];
    this.calibrationSamples = [];
    this.nextT = null;
    this.cal = null;
  }

  push(t: number, measured: Measured): void {
    const period = 1000 / this.cfg.sample_hz;
    if (this.nextT !== null && t + 1e-6 < this.nextT) return;
    // Same grid rule as extract.py, so 30 fps live matches thinned video.
    this.nextT = Math.max((this.nextT ?? t) + period, t);
    const sample = { t, ...measured };
    this.samples.push(sample);
    const cutoff = t - this.cfg.window_s * 1000;
    while (this.samples.length && this.samples[0].t <= cutoff) this.samples.shift();

    if (!this.cal) {
      this.calibrationSamples.push(sample);
      const first = this.calibrationSamples[0].t;
      if (t - first >= this.cfg.calibration_s * 1000) {
        this.cal = calibrate(this.calibrationSamples, this.cfg);
        // A failed attempt tries again on the next stretch of samples.
        this.calibrationSamples = [];
      }
    }
  }

  features(): number[] | null {
    return this.cal ? windowFeatures(this.samples, this.cal, this.cfg) : null;
  }
}
